mapper.update:
UPDATE volt_member
nickname = #{nickname}, avatar_url = #{avatarUrl}, goal = #{goal}, height_cm = #{heightCm}, weight_kg = #{weightKg},
WHERE member_id = #{memberId}

UPDATE volt_member
SET phone = #{phone}, phone_bound = 1
WHERE member_id = #{memberId}

mapper.select:
SELECT token, member_id, expires_at, created_at
FROM volt_token
WHERE token = #{token}

SELECT id, phone, code, purpose, expires_at, consumed, attempts, created_at
FROM volt_otp
WHERE phone = #{phone}
  AND purpose = #{purpose}
ORDER BY id DESC
LIMIT 1
